import { validate } from '../route/context/extract.ts'
import * as Route from '../route/index.ts'

interface BunRequest extends Request {
  readonly params: Record<string, string>
}

export const routes = <const R extends Route.Route<any, any>[]>(
  routes: R,
): Route.Compute<Routes<R[number]['schema']>> => {
  let r: any = {}
  for (const route of routes) {
    if (!route.schema.path) continue
    if (!r[route.schema.path]) r[route.schema.path] = {}
    if (!r[route.schema.path][route.schema.method]) r[route.schema.path][route.schema.method] = adapt(route)
  }
  return r
}

export type Routes<R extends Route.RouteSpec> = {
  [K in R['path'] & string]: {
    [M in Extract<R, { path: K }>['method'] & string]: (req: BunRequest) => Promise<Response>
  }
}

export const adapt = <I extends Route.RouteSpec, C>(rt: Route.Route<I, C>) =>
  Route.adapt<BunRequest, any, I>(rt, { path: extractPath(rt) })

const extractPath = <I extends Route.RouteSpec>(rt: Route.Route<I>) => {
  const schema = rt.schema.params
  if (schema === undefined) return () => undefined
  return async (req: BunRequest) => validate(schema, req.params)
}
